import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Create plane geometry with 512:320 aspect ratio (1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1);

  // Load texture asynchronously via cached loader
  const imageTexture = ctx.textureLoader.load(config.assets.imageUrl);

  // Create material with TSL shader nodes
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: texture(imageTexture),
    transparent: true,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement from config
  mesh.position.set(
    config.scenePosition[0],
    config.scenePosition[1],
    config.scenePosition[2]
  );
  mesh.rotation.set(
    config.sceneRotation[0],
    config.sceneRotation[1],
    config.sceneRotation[2]
  );
  mesh.scale.set(
    config.sceneScale[0],
    config.sceneScale[1],
    config.sceneScale[2]
  );

  group.add(mesh);

  // Setup cleanup function to dispose resources
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    imageTexture.dispose();
  };

  // Setup event handlers (empty for static card)
  group.userData.handlers = {};

  return group;
}
